        var key = nm + ':' + k;
        if (!ptrs[key]) return;
        colorPtr(key, ACCENT, 3.2);
        tag(PB.gl, ptrs[key].lx, ptrs[key].ly, nm);
      });
    }
    if (state.mode !== 'b' && PA) {
      PA.gl.circle((NR + 10) * 2).center(X[k], A_ROWS[ROW[k]]).fill('none')
        .stroke({ color: ACCENT, width: 4 });
    }
  }

  /* ---------- render ---------- */
  function render() {
    draw.clear();
    ptrs = {}; PA = null; PB = null;
    if (state.mode === 'a' || state.mode === 'both') drawPanelA(draw.group());
    if (state.mode === 'b' || state.mode === 'both') drawPanelB(draw.group());
    applyHighlight();

    if (state.mode === 'a') draw.viewbox(0, 0, W, 530);
    else if (state.mode === 'b') draw.viewbox(0, 508, W, 662);
    else draw.viewbox(0, 0, W, 1172);

    var ib = document.getElementById('insertAnimInput');
    if (ib) ib.textContent = state.ins > 0 ? '↺ Reset (remove 21)' : '▶ FIB-HEAP-INSERT(H, 21)';
    var si = document.getElementById('selInfo');
    if (si) {
      if (state.sel == null) si.innerHTML = 'Click any node to reveal its four pointers <i>p</i>, <i>child</i>, <i>left</i>, <i>right</i>.';
      else {
        var grp = groupOf(state.sel), i = grp.indexOf(state.sel), n = grp.length;
        si.innerHTML = '<b>' + state.sel + '</b>: p=' + (PARENT[state.sel] || 'NIL') +
          ', child=' + (firstChild(state.sel) || 'NIL') +
          ', left=' + grp[(i - 1 + n) % n] + ', right=' + grp[(i + 1) % n] +
          (n === 1 ? ' — alone in its ring, so left = right = itself.' : '');
      }
    }
    var sel = document.getElementById('viewModeInput');
    if (sel && sel.value !== state.mode) sel.value = state.mode;
  }

  /* ---------- interactions ---------- */
  function selectNode(k) {
    if (state.sel === k) { state.sel = null; render(); hidePopup(); return; }
    state.sel = k;
    render();
    var p = popupFor(k);
    showPopup(p.t, p.b);
  }
  function clearSel() { state.sel = null; hidePopup(); render(); }

  function setMode(m) { state.mode = m; render(); }

  function clearTimers() { insTimers.forEach(clearTimeout); insTimers = []; }

  function startInsert() {
    clearTimers();
    if (state.mode === 'a') state.mode = 'b';
    state.ins = 1; state.sel = null; render();
    insTimers.push(setTimeout(function () { state.ins = 2; render(); }, 1200));
    insTimers.push(setTimeout(function () {
      state.ins = 3; render();
      showPopup('FIB-HEAP-INSERT(H, 21) — O(1)',
        'The new key becomes a one-node tree whose left and right point to itself. Splicing it into the root list rewires exactly four pointers (17.right, 21.right, 24.left, 21.left). Since 21 > 3, H.min does not move, and no existing tree is touched — all consolidation work is deferred to EXTRACT-MIN.');
    }, 2400));
  }

  function trigger_insertAnim() {
    if (state.ins > 0) { clearTimers(); state.ins = 0; render(); return; }
    startInsert();
  }

  /* ---------- demo steps ---------- */
  var steps = [
    {
      t: 'The abstract view', m: 'a', sel: null, ins: false,
      n: 'Five min-heap-ordered trees hang from a root list drawn as a dashed line; H.min points at the smallest root, 3. Black nodes 18, 39 and 26 are marked — each has lost one child since it became a child of its current parent.'
    },
    {
      t: 'Same heap, real pointers', m: 'b', sel: null, ins: false,
      n: 'Switch to panel (b): the dashed root line becomes a circular doubly linked list, and every sibling group — even single children like 30 and 35 — becomes its own circular list with left and right arrows.'
    },
    {
      t: 'Four pointers per node', m: 'b', sel: 18, ins: false,
      n: 'Click node 18 (highlighted), then 52, then 30. Each node shows p up to its parent, child down to just one child, and left/right around its sibling ring; a lone child\'s left and right point to itself.'
    },
    {
      t: 'Compare the two views', m: 'both', sel: 52, ins: false,
      n: 'Side by side, the tree edge 3—52 in (a) is revealed in (b) as 52\'s parent pointer plus membership in the sibling ring that 3\'s single child pointer reaches.'
    },
    {
      t: 'Insert in O(1)', m: 'b', sel: null, ins: true,
      n: 'Play FIB-HEAP-INSERT(H, 21): the new node becomes a one-node tree, four pointers splice it into the root list, and since 21 > 3 the H.min pointer does not move. No tree is ever touched.'
    }
  ];

  function applyStep(i) {
    i = Math.max(0, Math.min(steps.length - 1, i));
    state.step = i;
    var s = steps[i];
    clearTimers();
    state.mode = s.m;
    state.sel = s.sel;
    state.ins = 0;
    hidePopup();
    document.getElementById('demoNarration').textContent = s.n;
    document.getElementById('stepLabel').textContent = 'Step ' + (i + 1) + ' / ' + steps.length + ' · ' + s.t;
    render();
    if (s.ins) insTimers.push(setTimeout(startInsert, 260));
  }
  function nextStep() { applyStep(state.step + 1); }
  function prevStep() { applyStep(state.step - 1); }

  /* expose */
  window.setMode = setMode;
  window.clearSel = clearSel;
  window.trigger_insertAnim = trigger_insertAnim;
  window.nextStep = nextStep;
  window.prevStep = prevStep;

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

