  var MARKED = { 18: 1, 39: 1, 26: 1 };
  var PARENT = { 18: 3, 52: 3, 38: 3, 30: 17, 26: 24, 46: 24, 39: 18, 41: 38, 35: 26 };

  // each sibling ring: p = parent, list = circular order, child = the ONE node p.child points at
  var SUB = [
    { p: 3, list: [18, 52, 38], child: 52 },
    { p: 17, list: [30], child: 30 },
    { p: 24, list: [26, 46], child: 26 },
    { p: 18, list: [39], child: 39 },
    { p: 38, list: [41], child: 41 },
    { p: 26, list: [35], child: 35 }
  ];

  var A_ROWS = [145, 265, 385];
  var B_ROWS = [600, 770, 940];

  var state = { mode: 'both', sel: null, ins: 0, step: 0 };
  var ptrs = {};
  var PA = null, PB = null;
  var insTimers = [];

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.attr('preserveAspectRatio', 'xMidYMid meet');

  /* ---------- helpers ---------- */
  function rootList() {
    return state.ins >= 2 ? [23, 7, 3, 17, 21, 24] : [23, 7, 3, 17, 24];
  }
  function allGroups() {
    return [{ p: null, list: rootList() }].concat(SUB);
  }
  function groupOf(k) {
    var gs = allGroups();
    for (var i = 0; i < gs.length; i++) if (gs[i].list.indexOf(k) >= 0) return gs[i].list;
    return [k];
  }
  function childOf(k) {
    for (var i = 0; i < SUB.length; i++) if (SUB[i].p === k) return SUB[i].child;
    return null;
  }
  function nodesPresent() {
    var ks = [23, 7, 3, 17, 24, 18, 52, 38, 30, 26, 46, 39, 41, 35];
    if (state.ins >= 1) ks.push(21);
    return ks;
  }

  function head(g, x, y, ux, uy, s, color) {
    var L = Math.hypot(ux, uy) || 1; ux /= L; uy /= L;
    var px = -uy, py = ux, w = s * 0.42;
    g.polygon([[x, y],
    [x - ux * s + px * w, y - uy * s + py * w],
    [x - ux * s - px * w, y - uy * s - py * w]]).fill(color).stroke('none');
  }

  function seg(g, x1, y1, x2, y2, color, w, arrowEnd) {
    var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1;
    var ux = dx / L, uy = dy / L;
    var ex = arrowEnd ? x2 - ux * 8 : x2, ey = arrowEnd ? y2 - uy * 8 : y2;
    g.line(x1, y1, ex, ey).stroke({ color: color, width: w, linecap: 'butt' });
    if (arrowEnd) head(g, x2, y2, ux, uy, 14, color);
  }

  function reg(key, gg, lx, ly, desc) {
    ptrs[key] = { g: gg, lx: lx, ly: ly, desc: desc };
    gg.css('cursor', 'help');
    gg.on('mousemove', function (e) { showTooltip(desc, e); });
    gg.on('mouseleave', hideTooltip);
  }

  function colorPtr(key, color, w) {
    var p = ptrs[key]; if (!p) return;
    p.g.each(function () {
      if (this.type === 'polygon') this.fill(color);
      else this.stroke({ color: color, width: w });
    });
    p.g.front();
  }

  function tag(g, x, y, txt) {
    var t = g.text(txt).font({ family: SERIF, size: 26, anchor: 'middle', style: 'italic' }).fill(ACCENT);
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
    t.center(x, y);
    return t;
  }

  function label(g, x, y, txt, size, color, italic, weight) {
    var t = g.text(txt).font({
      family: SERIF, size: size, anchor: 'middle',
      style: italic ? 'italic' : 'normal', weight: weight || 'normal'
    }).fill(color);
    t.center(x, y);
    return t;
  }

  /* ---------- racetracks (circular doubly linked list) ---------- */
  function wrapUpper(sx, yu, ex, xL, xR, yt, R) {
    return 'M' + sx + ',' + yu + ' H' + (xR - R) +
      ' Q' + xR + ',' + yu + ' ' + xR + ',' + (yu - R) +
      ' V' + (yt + R) + ' Q' + xR + ',' + yt + ' ' + (xR - R) + ',' + yt +
      ' H' + (xL + R) + ' Q' + xL + ',' + yt + ' ' + xL + ',' + (yt + R) +
      ' V' + (yu - R) + ' Q' + xL + ',' + yu + ' ' + (xL + R) + ',' + yu +
      ' H' + ex;
  }
  function wrapLower(sx, yl, ex, xL, xR, yb, R) {
    return 'M' + sx + ',' + yl + ' H' + (xL + R) +
      ' Q' + xL + ',' + yl + ' ' + xL + ',' + (yl + R) +
      ' V' + (yb - R) + ' Q' + xL + ',' + yb + ' ' + (xL + R) + ',' + yb +
      ' H' + (xR - R) + ' Q' + xR + ',' + yb + ' ' + xR + ',' + (yl + R) +
      ' V' + (yl + R) + ' Q' + xR + ',' + yl + ' ' + (xR - R) + ',' + yl +
      ' H' + ex;
  }

  function drawRing(g, list, y, color) {
    color = color || '#000';
    var n = list.length, r = NR, R = 18;
    var xs = list.map(function (k) { return X[k]; });
    var yu = y - 12, yl = y + 12, yt = y - 60, yb = y + 60;
    var xL = xs[0] - r - 45, xR = xs[n - 1] + r + 45;
    var i, gg;

    for (i = 0; i < n - 1; i++) {
      gg = g.group();
      seg(gg, xs[i] + r * 0.94, yu, xs[i + 1] - r * 0.94, yu, color, 2.2, true);
      reg('right:' + list[i], gg, (xs[i] + xs[i + 1]) / 2, yu - 20, list[i] + '.right = ' + list[i + 1]);
    }
    gg = g.group();
    var sx = xs[n - 1] + r * 0.94, ex = xs[0] - r * 0.94;
    gg.path(wrapUpper(sx, yu, ex - 10, xL, xR, yt, R)).fill('none').stroke({ color: color, width: 2.2 });
    head(gg, ex, yu, 1, 0, 14, color);
    reg('right:' + list[n - 1], gg, xs[n - 1] + r + 30, yu - 22, list[n - 1] + '.right = ' + list[0] + '  (wraps around)');

    for (i = n - 1; i > 0; i--) {
      gg = g.group();
      seg(gg, xs[i] - r * 0.94, yl, xs[i - 1] + r * 0.94, yl, color, 2.2, true);
      reg('left:' + list[i], gg, (xs[i] + xs[i - 1]) / 2, yl + 26, list[i] + '.left = ' + list[i - 1]);
    }
    gg = g.group();
    sx = xs[0] - r * 0.94; ex = xs[n - 1] + r * 0.94;
    gg.path(wrapLower(sx, yl, ex + 10, xL, xR, yb, R)).fill('none').stroke({ color: color, width: 2.2 });
    head(gg, ex, yl, -1, 0, 14, color);
    reg('left:' + list[0], gg, xs[0] - r - 30, yl + 26, list[0] + '.left = ' + list[n - 1] + '  (wraps around)');
  }

  /* ---------- parent / child pointers ---------- */
  function drawDouble(g, pk, ck, rows) {
    var x1 = X[pk], y1 = rows[ROW[pk]], x2 = X[ck], y2 = rows[ROW[ck]];
    var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
    var nx = -dy, ny = dx, o = 9;
    var mx = (x1 + x2) / 2, my = (y1 + y2) / 2;

    var g1 = g.group();
    seg(g1, x1 + dx * NR + nx * o, y1 + dy * NR + ny * o, x2 - dx * NR + nx * o, y2 - dy * NR + ny * o, '#000', 2.2, true);
    reg('child:' + pk, g1, mx + nx * 34, my + ny * 34, pk + '.child = ' + ck);

    var g2 = g.group();
    seg(g2, x2 - dx * NR - nx * o, y2 - dy * NR - ny * o, x1 + dx * NR - nx * o, y1 + dy * NR - ny * o, '#000', 2.2, true);
    reg('p:' + ck, g2, mx - nx * 34, my - ny * 34, ck + '.p = ' + pk);
  }

  function drawUp(g, ck, pk, rows) {
    var x1 = X[ck], y1 = rows[ROW[ck]], x2 = X[pk], y2 = rows[ROW[pk]];
    var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
    var gg = g.group();
    seg(gg, x1 + dx * NR, y1 + dy * NR, x2 - dx * NR, y2 - dy * NR, '#000', 2.2, true);
    var nx = -dy, ny = dx;
    reg('p:' + ck, gg, (x1 + x2) / 2 + nx * 30, (y1 + y2) / 2 + ny * 30, ck + '.p = ' + pk);
  }

  /* ---------- nodes ---------- */
  function tipText(k) {
    var grp = groupOf(k), i = grp.indexOf(k), n = grp.length;
    return k + (MARKED[k] ? '  (marked)' : '  (unmarked)') +
      '   p=' + (PARENT[k] || 'NIL') + ', child=' + (childOf(k) || 'NIL') +
      ', left=' + grp[(i - 1 + n) % n] + ', right=' + grp[(i + 1) % n];
  }

  function popupFor(k) {
    var grp = groupOf(k), i = grp.indexOf(k), n = grp.length;
    var body = 'Pointers: p = ' + (PARENT[k] || 'NIL') +
      ' · child = ' + (childOf(k) || 'NIL') +
      ' · left = ' + grp[(i - 1 + n) % n] +
      ' · right = ' + grp[(i + 1) % n] + '. ';
    body += n === 1
      ? 'This node is alone in its sibling list, so left and right point back to itself — the list is still circular, which is why splicing never needs a special case.'
      : 'left and right walk the circular sibling list; child reaches only ONE child, and the rest are found by walking that child\'s ring.';
    body += MARKED[k]
      ? ' It is black (marked): it has lost one child since becoming a child of its current parent.'
      : ' It is gray (unmarked).';
    return { t: 'Node ' + k, b: body };
  }

  function drawNode(g, k, y, accent) {
    var isMark = !!MARKED[k];
    var fill = accent ? '#fff' : (isMark ? '#000' : GRAY);
    var strokeC = accent ? ACCENT : '#000';
    g.circle(NR * 2).center(X[k], y).fill(fill).stroke({ color: strokeC, width: accent ? 3.6 : 2.4 });
    var t = g.text(String(k)).font({
      family: SERIF, size: 32, anchor: 'middle', weight: isMark ? 'bold' : 'normal'
    }).fill(accent ? ACCENT : (isMark ? '#fff' : '#000'));
    t.center(X[k], y);
    var hit = g.circle(NR * 2).center(X[k], y).fill('#fff').opacity(0).css('cursor', 'pointer');
    hit.on('mousemove', function (e) { showTooltip(tipText(k), e); });
    hit.on('mouseleave', hideTooltip);
    hit.on('click', function () { selectNode(k); });
  }

  function hmin(g, x, ytext, y1, y2) {
    var t = g.text('H.min').font({ family: SERIF, size: 38, anchor: 'middle', style: 'italic' }).fill('#000');
    t.center(x, ytext);
    seg(g, x, y1, x, y2, '#000', 2.8, true);
  }

  /* ---------- panel (a) ---------- */
  function drawPanelA(root) {
    var gp = root.group(), gn = root.group(), gl = root.group();
    PA = { gl: gl };
    label(gp, 56, A_ROWS[0], '(a)', 42, '#000');
    hmin(gp, X[3], 32, 60, 104);

    var rl = rootList();
    for (var i = 0; i < rl.length - 1; i++) {
      gp.line(X[rl[i]] + NR, A_ROWS[0], X[rl[i + 1]] - NR, A_ROWS[0])
        .stroke({ color: '#000', width: 2.2, dasharray: '13,11' });
    }
    Object.keys(PARENT).forEach(function (ck) {
      var k = +ck, pk = PARENT[k];
      var x1 = X[pk], y1 = A_ROWS[ROW[pk]], x2 = X[k], y2 = A_ROWS[ROW[k]];
      var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy); dx /= L; dy /= L;
      gp.line(x1 + dx * NR, y1 + dy * NR, x2 - dx * NR, y2 - dy * NR).stroke({ color: '#000', width: 2.2 });
    });
    nodesPresent().forEach(function (k) {
      drawNode(gn, k, A_ROWS[ROW[k]], k === 21);
    });
  }

  /* ---------- panel (b) ---------- */
  function drawPanelB(root) {
    var gp = root.group(), gn = root.group(), gl = root.group();
    PB = { gl: gl };
    label(gp, 56, B_ROWS[0], '(b)', 42, '#000');
    hmin(gp, X[3], 497, 524, 560);

    drawRing(gp, rootList(), B_ROWS[0], '#000');
    if (state.ins === 1) drawRing(gp, [21], B_ROWS[0], ACCENT);

    SUB.forEach(function (s) {
      drawRing(gp, s.list, B_ROWS[ROW[s.list[0]]], '#000');
      drawDouble(gp, s.p, s.child, B_ROWS);
      s.list.forEach(function (c) { if (c !== s.child) drawUp(gp, c, s.p, B_ROWS); });
    });

    if (state.ins >= 2) {
      ['right:17', 'right:21', 'left:24', 'left:21'].forEach(function (k) { colorPtr(k, ACCENT, 3.2); });
    }

    nodesPresent().forEach(function (k) {
      drawNode(gn, k, B_ROWS[ROW[k]], k === 21);
    });

    if (state.ins === 1) {
      label(gl, 1050, 513, 'new singleton tree:  21.left = 21.right = 21', 25, ACCENT, true)
        .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 6, 'stroke-linejoin': 'round' });
    } else if (state.ins >= 2) {
      label(gl, 1020, 513, 'spliced in: 4 pointers changed · 21 > 3, so H.min unchanged', 25, ACCENT, true)
        .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 6, 'stroke-linejoin': 'round' });
    }
  }

  /* ---------- highlight ---------- */
  function applyHighlight() {
    var k = state.sel;
    if (k == null) return;
    if (state.mode !== 'a' && PB) {
      PB.gl.circle((NR + 11) * 2).center(X[k], B_ROWS[ROW[k]]).fill('none')
        .stroke({ color: ACCENT, width: 4 });
      ['right', 'left', 'p', 'child'].forEach(function (nm) {
        var key = nm + ':' + k;
        if (!ptrs[key]) return;
        colorPtr(key, ACCENT, 3.2);
        tag(PB.gl, ptrs[key].lx, ptrs[key].ly, nm);
      });
    }
    if (state.mode !== 'b' && PA) {
      PA.gl.circle((NR + 11) * 2).center(X[k], A_ROWS[ROW[k]]).fill('none')
        .stroke({ color: ACCENT, width: 4 });
    }
  }

  /* ---------- render ---------- */
  function render() {
    draw.clear();
    ptrs = {}; PA = null; PB = null;
    if (state.mode === 'a' || state.mode === 'both') drawPanelA(draw.group());
    if (state.mode === 'b' || state.mode === 'both') drawPanelB(draw.group());
    applyHighlight();

    if (state.mode === 'a') draw.viewbox(0, 0, W, 442);
    else if (state.mode === 'b') draw.viewbox(0, 458, W, 558);
    else draw.viewbox(0, 0, W, 1016);

    var ib = document.getElementById('insertAnimInput');
    if (ib) ib.textContent = state.ins > 0 ? '↺ Reset (remove 21)' : '▶ FIB-HEAP-INSERT(H, 21)';
    var si = document.getElementById('selInfo');
    if (si) {
      if (state.sel == null) si.innerHTML = 'Click any node to reveal its four pointers <i>p</i>, <i>child</i>, <i>left</i>, <i>right</i>.';
      else {
        var grp = groupOf(state.sel), i = grp.indexOf(state.sel), n = grp.length;
        si.innerHTML = '<b>' + state.sel + '</b>: p=' + (PARENT[state.sel] || 'NIL') +
          ', child=' + (childOf(state.sel) || 'NIL') +
          ', left=' + grp[(i - 1 + n) % n] + ', right=' + grp[(i + 1) % n] +
          (n === 1 ? ' — alone in its ring, so left = right = itself.' : '');
      }
    }
    var sel = document.getElementById('viewModeInput');
    if (sel && sel.value !== state.mode) sel.value = state.mode;
  }

  /* ---------- interactions ---------- */
  function selectNode(k) {
    if (state.sel === k) { state.sel = null; render(); hidePopup(); return; }
    state.sel = k;
    render();
    var p = popupFor(k);
    showPopup(p.t, p.b);
  }
  function clearSel() { state.sel = null; hidePopup(); render(); }
  function setMode(m) { state.mode = m; render(); }
  function clearTimers() { insTimers.forEach(clearTimeout); insTimers = []; }

  function startInsert() {
    clearTimers();
    if (state.mode === 'a') state.mode = 'b';
    state.ins = 1; state.sel = null; render();
    insTimers.push(setTimeout(function () { state.ins = 2; render(); }, 1300));
    insTimers.push(setTimeout(function () {
      state.ins = 3; render();
      showPopup('FIB-HEAP-INSERT(H, 21) — O(1)',
        'The new key becomes a one-node tree whose left and right point to itself. Splicing it into the root list rewires exactly four pointers (17.right, 21.right, 24.left, 21.left). Since 21 > 3, H.min does not move, and no existing tree is touched — all consolidation work is deferred to EXTRACT-MIN.');
    }, 2600));
  }

  function trigger_insertAnim() {
    if (state.ins > 0) { clearTimers(); state.ins = 0; render(); return; }
    startInsert();
  }

  /* ---------- demo steps ---------- */
  var steps = [
    {
      t: 'One heap, two pictures', m: 'both', sel: null, ins: false,
      n: 'The same Fibonacci heap drawn twice. (a) is the abstract picture: five min-heap-ordered trees hanging from a dashed root list, with H.min on the smallest root, 3. (b) is what memory actually holds: the very same nodes, wired by pointers.'
    },
    {
      t: 'The abstract view', m: 'a', sel: null, ins: false,
      n: 'Panel (a) alone. Every tree obeys the heap property, and the black nodes 18, 39 and 26 are marked — each has lost one child since it became a child of its current parent. The dashed line is only shorthand for "these roots form a list".'
    },
    {
      t: 'Same heap, real pointers', m: 'b', sel: null, ins: false,
      n: 'Panel (b): the dashed root line is really a circular doubly linked list — an upper track of right pointers, a lower track of left pointers, wrapping around at both ends. Every sibling group, even a lone child like 30 or 35, is its own circular list.'
    },
    {
      t: 'Four pointers per node', m: 'b', sel: 52, ins: false,
      n: 'Node 52 is highlighted with its four pointers labelled. p goes up to 3, left and right walk the sibling ring 18 → 52 → 38 → back to 18, and 3.child reaches only 52 — the other children are found by walking that ring. Click 30 to see a ring of one, where left = right = itself.'
    },
    {
      t: 'Insert in O(1)', m: 'b', sel: null, ins: true,
      n: 'FIB-HEAP-INSERT(H, 21): the new key becomes a one-node tree, four pointer writes splice it into the root list, and since 21 > 3 the H.min pointer never moves. No tree is touched — the real work is deferred to extract-min.'
    }
  ];

  function applyStep(i) {
    i = Math.max(0, Math.min(steps.length - 1, i));
    state.step = i;
    var s = steps[i];
    clearTimers();
    state.mode = s.m;
    state.sel = s.sel;
    state.ins = 0;
    hidePopup();
    document.getElementById('demoNarration').textContent = s.n;
    document.getElementById('stepLabel').textContent = 'Step ' + (i + 1) + ' / ' + steps.length + ' · ' + s.t;
    render();
    if (s.ins) insTimers.push(setTimeout(startInsert, 300));
  }
  function nextStep() { applyStep(state.step + 1); }
  function prevStep() { applyStep(state.step - 1); }

  window.setMode = setMode;
  window.clearSel = clearSel;
  window.trigger_insertAnim = trigger_insertAnim;
  window.nextStep = nextStep;
  window.prevStep = prevStep;

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A Fibonacci heap is a circular doubly linked list of min-heap-ordered trees, and its abstract tree picture and its concrete four-pointer-per-node representation are the same structure viewed at two levels of abstraction.
KEY INSIGHT (what students should walk away understanding): A Fibonacci heap is lazy because its shape lives entirely in pointers: adding or removing a tree is just relinking a circular doubly linked list, so insert costs O(1) and all the real work is deferred to extract-min.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A Fibonacci heap is a circular doubly linked list of min-heap-ordered trees, and its abstract tree picture and its concrete four-pointer-per-node representation are the same structure viewed at two levels of abstraction.",
  "figureType": "network_diagram",
  "elements": [
    "Panel label '(a)' at left of the upper diagram",
    "Panel label '(b)' at left of the lower diagram",
    "H.min pointer label in italic serif with a downward arrow above root node 3 (one instance per panel)",
    "Root list nodes, left to right: 23, 7, 3, 17, 24 — light gray filled circles with black numerals and black outlines",
    "Panel (a) dashed horizontal line connecting the five root nodes (root list shown abstractly)",
    "Panel (a) solid tree edges: 3→18, 3→52, 3→38; 18→39; 38→41; 17→30; 24→26, 24→46; 26→35",
    "Marked nodes 18, 39, 26 drawn as solid black circles with bold white numerals in BOTH panels",
    "Unmarked internal nodes 52, 38, 41, 30, 46, 35 as light gray circles",
    "Panel (b) root-list linked structure: two concentric rounded 'racetrack' wrap-around paths enclosing the root list, one carrying rightward (next/right) arrows, one carrying leftward (prev/left) arrows, forming a circular doubly linked list",
    "Panel (b) child-list racetracks for each sibling group: {18,52,38}, {30}, {26,46}, {39}, {41}, {35} — each a circular doubly linked list, including single-node lists that loop back to themselves",
    "Panel (b) vertical double arrows between a parent and one child (parent's child pointer down, child's parent pointer up) for 3↔18, 17↔30, 24↔26, 18↔39, 38↔41, 26↔35",
    "Panel (b) diagonal upward parent pointers from 52 and 38 to 3, and from 46 to 24",
    "Legend/annotation text: 'gray = unmarked, black = marked (has lost one child since becoming a child)'",
    "Optional highlight overlay: colored halos and pointer labels 'p', 'child', 'left', 'right' when a node is selected",
    "Optional inserted node (e.g. key 21) drawn in a highlight color during the insert animation, with its two new root-list pointer arrows"
  ],
  "interactions": [
    {
      "id": "viewMode",
      "type": "toggle",
      "label": "Representation",
      "options": [
        "Abstract tree (a)",
        "Pointer diagram (b)",
        "Side by side"
      ],
      "default": "Abstract tree (a)",
      "teaches": "The dashed root line and plain tree edges of the textbook picture are shorthand for circular doubly linked sibling lists plus parent/child pointers — same heap, two levels of detail."
    },
    {
      "id": "inspectNode",
      "type": "click",
      "teaches": "Every node carries exactly four pointers — p, child, left, right — and in a one-node sibling list left and right point back to the node itself, which is why splicing is always O(1)."
    },
    {
      "id": "insertAnim",
      "type": "animation",
      "label": "FIB-HEAP-INSERT(H, 21)",
      "loop": false,
      "teaches": "Insertion creates a singleton tree, rewires only four pointers to splice it into the root list, and compares one key against H.min — constant time, no consolidation."
    }
  ],
  "demo_steps": [
    {
      "title": "The abstract view",
